replacements.after:
/* Read each lesson in normal page flow, without locking the screen height. */
.school-compact-lesson .school-lesson-shell{min-height:100svh;height:auto;display:flex;flex-direction:column;box-sizing:border-box}
.school-compact-lesson .school-lesson-shell>main{display:block;flex:1 0 auto;min-height:0}
.school-compact-lesson .school-footer{padding:4px 0 0}
.school-compact-lesson .school-lesson-navigation{margin-top:8px}
.school-lesson-about[open]{max-height:none;overflow:visible}
.school-compact-lesson .lesson-player{display:block;min-height:0}
.lesson-player>.lesson-slide{display:block;min-height:0}
.lesson-figure-drawing svg{width:clamp(170px,26svh,220px)}
.lesson-figure .learning-outline,.lesson-figure .learning-line,.lesson-figure .learning-node circle:not(.learning-node-hit){vector-effect:non-scaling-stroke;stroke-width:1px}
.learning-canvas .learning-node-value{font-size:26px}.learning-canvas.is-basic .learning-node-value{font-size:30px}
.learning-canvas .learning-diagram-label{font-size:20px}.learning-canvas .learning-node-index{font-size:15px}
.school-compact-lesson .learning-workshop.is-embedded{display:block;min-height:0;overflow:visible}
.learning-workshop.is-embedded .learning-task{min-height:0;overflow:visible}
.school-compact-lesson .learning-workshop.is-finished,.school-compact-lesson .school-lesson-quiz{min-height:0;overflow:visible}
.learning-workshop.is-embedded .learning-map>svg{width:clamp(190px,27svh,250px)}
.learning-workshop.is-embedded>.learning-answer-area{margin-top:9px}
